window.ScripturaLexicons.BDAG_PART_0156 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-euphrates-bdag\" data-source=\"BDAG\" data-search=\"Εὐφράτης, ου, ὁ Euphrátēs nome próprio masculino Eufrates BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Εὐφράτης, ου, ὁ</td><td>nome próprio masculino</td><td>Eufrates</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-euphrosyne-bdag\" data-source=\"BDAG\" data-search=\"εὐφροσύνη, ης, ἡ euphrosýnē substantivo feminino alegria; júbilo; contentamento BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εὐφροσύνη, ης, ἡ</td><td>substantivo feminino</td><td>alegria; júbilo; contentamento</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eucharisteo-bdag\" data-source=\"BDAG\" data-search=\"εὐχαριστέω eucharistéō verbo ser grato; agradecer; dar graças; orar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εὐχαριστέω</td><td>verbo</td><td>ser grato; agradecer; dar graças; orar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eucharistia-bdag\" data-source=\"BDAG\" data-search=\"εὐχαριστία, ας, ἡ eucharistía substantivo feminino gratidão; ação de graças; Eucaristia; Ceia do Senhor BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εὐχαριστία, ας, ἡ</td><td>substantivo feminino</td><td>gratidão; ação de graças; Eucaristia; Ceia do Senhor</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eucharistos-bdag\" data-source=\"BDAG\" data-search=\"εὐχάριστος, ον eucháristos adjetivo grato; agradecido BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εὐχάριστος, ον</td><td>adjetivo</td><td>grato; agradecido</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eucheres-bdag\" data-source=\"BDAG\" data-search=\"εὐχερής, ές, eucherḗs adjetivo inclinado; propenso; temerário; fácil BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εὐχερής, ές,</td><td>adjetivo</td><td>inclinado; propenso; temerário; fácil</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-euche-bdag\" data-source=\"BDAG\" data-search=\"εὐχή, ῆς, ἡ euchḗ substantivo feminino oração; voto solene BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εὐχή, ῆς, ἡ</td><td>substantivo feminino</td><td>oração; voto solene</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-euchomai-bdag\" data-source=\"BDAG\" data-search=\"εὔχομαι eúchomai verbo depoente orar; pedir a Deus; desejar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εὔχομαι</td><td>verbo depoente</td><td>orar; pedir a Deus; desejar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-euchrestos-bdag\" data-source=\"BDAG\" data-search=\"εὔχρηστος, ον eúchrēstos adjetivo útil; proveitoso; prestativo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εὔχρηστος, ον</td><td>adjetivo</td><td>útil; proveitoso; prestativo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-eupsycheo-bdag\" data-source=\"BDAG\" data-search=\"εὐψυχέω eupsychéō verbo ficar animado; ter coragem; alegrar-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εὐψυχέω</td><td>verbo</td><td>ficar animado; ter coragem; alegrar-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-euodia-bdag\" data-source=\"BDAG\" data-search=\"εὐωδία, ας, ἡ euōdía substantivo feminino aroma; fragrância; bom perfume BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εὐωδία, ας, ἡ</td><td>substantivo feminino</td><td>aroma; fragrância; bom perfume</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-euonymos-bdag\" data-source=\"BDAG\" data-search=\"εὐώνυμος, ον euṓnymos adjetivo esquerdo; situado à esquerda BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εὐώνυμος, ον</td><td>adjetivo</td><td>esquerdo; situado à esquerda</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-euocheo-bdag\" data-source=\"BDAG\" data-search=\"εὐωχέω euōchéō verbo oferecer banquete; banquetear-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εὐωχέω</td><td>verbo</td><td>oferecer banquete; banquetear-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-euochia-bdag\" data-source=\"BDAG\" data-search=\"εὐωχία, ας, ἡ euōchía substantivo feminino banquete; festim BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">εὐωχία, ας, ἡ</td><td>substantivo feminino</td><td>banquete; festim</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-ephagon-bdag\" data-source=\"BDAG\" data-search=\"ἔφαγον éphagon aoristo verbal remissivo ver ἐσθίω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἔφαγον</td><td>aoristo verbal remissivo</td><td>ver ἐσθίω</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-ephallomai-bdag\" data-source=\"BDAG\" data-search=\"ἐφάλλομαι ephállomai verbo depoente saltar sobre; lançar-se contra BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐφάλλομαι</td><td>verbo depoente</td><td>saltar sobre; lançar-se contra</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-ephapax-bdag\" data-source=\"BDAG\" data-search=\"ἐφάπαξ ephápax advérbio de uma só vez; uma vez por todas BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐφάπαξ</td><td>advérbio</td><td>de uma só vez; uma vez por todas</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-ephesinos-bdag\" data-source=\"BDAG\" data-search=\"Ἐφέσινος, η, ον Ephésinos adjetivo efésino; de Éfeso BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἐφέσινος, η, ον</td><td>adjetivo</td><td>efésino; de Éfeso</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-ephesios-bdag\" data-source=\"BDAG\" data-search=\"Ἐφέσιος, ία, ιον Ephésios adjetivo e gentílico efésio; de Éfeso BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἐφέσιος, ία, ιον</td><td>adjetivo e gentílico</td><td>efésio; de Éfeso</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-ephesos-bdag\" data-source=\"BDAG\" data-search=\"Ἔφεσος, ου, ἡ Éphesos substantivo feminino; nome geográfico Éfeso BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἔφεσος, ου, ἡ</td><td>substantivo feminino; nome geográfico</td><td>Éfeso</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n","cardsHtml":"<article id=\"entry-euphrates-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Εὐφράτης, ου, ὁ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦Euphrátēs⟧</span><span class=\"separator\">·</span><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">Εὐφράτης</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span>; hebraico פְּרָת. Heródoto e posteriores; OGI 54, 13s.; 17; Gn 2:14 e outros; LXX; Fílon; Josefo; SibOr. <strong>Eufrates</strong>, o rio mais ocidental dos dois que delimitam entre si a Mesopotâmia. <span class=\"greek\">ὁ</span> <span class=\"greek\">ποταμὸς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">μέγας</span> <span class=\"greek\">Εὐ</span>., «o grande rio Eufrates» (Gn 15:18; Êx 23:31; cf. Diodoro Sículo 17, 75, 2 <span class=\"greek\">μέγας</span> <span class=\"greek\">ποταμὸς</span> … <span class=\"greek\">Στιβοίτης</span>, «grande rio … Estiboites»), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.9.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 9:14</a>; 16:12. Bibliografia: OEANE II 287–90.</p></section></article>\n<article id=\"entry-euphrosyne-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐφροσύνη, ης, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦euphrosýnē⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">εὐφροσύνη</span>, <span class=\"greek\">ης</span>, <span class=\"greek\">ἡ</span>. De <span class=\"greek\">εὔφρων</span>, «alegre»; Homero e posteriores; também PLips 119 II, 1. <strong>Alegria; júbilo; contentamento; jovialidade</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.28\" target=\"_blank\" rel=\"noopener noreferrer\">At 2:28</a> (Sl 15:11); 14:17 (cf. Sir 30:22; PsSol 15:3 <span class=\"greek\">εὐφροσύνη</span> <span class=\"greek\">καρδίας</span>, «alegria de coração»; ver <span class=\"greek\">καί</span> 1a<span class=\"greek\">δ</span>). Com <span class=\"greek\">ἀγαλλίασις</span>, «exultação», 1Cl 18:8 (Sl 50:10); B 1:6. <span class=\"greek\">ἀγάπη</span> <span class=\"greek\">εὐφροσύνης</span>, «amor acompanhado de alegria», ibid. <span class=\"greek\">τέκνα</span> <span class=\"greek\">εὐφροσύνης</span>, «filhos da alegria», isto é, filhos para os quais a alegria está reservada, B 7:1. <span class=\"greek\">ἔργον</span> <span class=\"greek\">εὐφροσύνης</span>, «obra de alegria», B 10:11. <span class=\"greek\">ἡμέραν</span> <span class=\"greek\">ἄγειν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">εὐ</span>., «celebrar um dia com alegria», B 15:9 (ver Jdt 12:13; Est 9:18). Bibliografia: DELG, s.v. <span class=\"greek\">φρήν</span>; <em>New Docs</em> 4, 152–54; M-M; TW; Sv.</p></section></article>\n<article id=\"entry-eucharisteo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐχαριστέω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eucharistéō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">εὐχαριστέω</span>. Ver <span class=\"greek\">χάρις</span>. Primeiro aoristo <span class=\"greek\">εὐχαρίστησα</span> (com aumento <span class=\"greek\">ηὐχ</span>- em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.21\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 1:21</a>, nas edições, exceto no <em>textus receptus</em>; ver W-S §12, 5b; Mlt-H. 191s.); primeiro aoristo passivo, subjuntivo, terceira pessoa do singular <span class=\"greek\">εὐχαριστηθῇ</span>; particípio <span class=\"greek\">εὐχαριστηθείς</span> em Justino.</p><p class=\"entry-text\">① <strong>Mostrar-se sob obrigação de retribuir: ser agradecido; sentir-se devedor de gratidão.</strong> Sentido comum em documentos diplomáticos nos quais o receptor de um benefício responde assegurando boa vontade (por exemplo, os decretos dos bizantinos em Demóstenes 18, 91s., encerrados por <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἐλλείψει</span> <span class=\"greek\">εὐχαριστῶν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ποιῶν</span> <span class=\"greek\">ὅ</span> <span class=\"greek\">τι</span> <span class=\"greek\">ἄν</span> <span class=\"greek\">δύνηται</span> <span class=\"greek\">ἀγαθόν</span>, «o povo do Quersoneso não cessará de ser agradecido e de fazer todo o bem que puder» ao povo de Atenas; cf. OGI 730, 11; IPriene 44, 8 e outros). Nesse sentido, a abreviação <span class=\"greek\">ἐ</span>. para <span class=\"greek\">εὐχαριστέω</span> equivale a <span class=\"greek\">χάριν</span> <span class=\"greek\">διδόναι</span>, «retribuir um benefício», em contraste com <span class=\"greek\">χάριν</span> <span class=\"greek\">εἰδέναι</span>, «reconhecer um benefício» (Frínico, p. 18 Lob.). Foi proposto para <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 18:11</a> (o fariseu estaria oferecendo retribuição mediante jejuns e dízimos, v. 12) e <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.4\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 16:4</a> («estar em dívida», a única passagem neotestamentária que menciona gratidão a seres humanos, como 2Mc 12:31); <strong>ambas, porém, também se enquadram na acepção ②</strong>.</p><p class=\"entry-text\">② <strong>Expressar apreço por benefícios ou bênçãos: dar graças; agradecer; manifestar gratidão</strong> (no sentido de «render graças» desde Políbio 16, 25, 1; Posidônio 87, Fgm. 36 [em Ateneu 5, 213e]; Diodoro Sículo 20, 34, 5; Plutarco, Mor. 505d; Epicteto; inscrições, papiros, LXX, Fílon; Josefo, Ant. 20, 12; cf. Frínico, p. 18 Lob.). <strong>À exceção de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.4\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 16:4</a></strong>, o verbo tem Deus como destinatário na literatura aqui abrangida (Diodoro Sículo 14, 29, 4; 16, 11, 1 <span class=\"greek\">τοῖς</span> <span class=\"greek\">θεοῖς</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀγαθῶν</span>, «aos deuses por seus benefícios»; Epicteto 1, 4, 32; 1, 10, 3; 2, 23, 5 <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span>; Artemidoro 4, 2, p. 206, 4 <span class=\"greek\">θῦε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">εὐχαρίστει</span>, «sacrifica e dá graças»; Herm. Wr. 1, 29 <span class=\"greek\">τ</span>. <span class=\"greek\">θεῷ</span>; SIG 995, 11 <span class=\"greek\">τ</span>. <span class=\"greek\">θεοῖς</span>; 1173, 9s.; UPZ 59, 10 [168 a.C.] <span class=\"greek\">τ</span>. <span class=\"greek\">θεοῖς</span>; PTebt 56, 9; BGU 423, 6 <span class=\"greek\">τ</span>. <span class=\"greek\">κυρίῳ</span> <span class=\"greek\">Σεράπιδι</span>, «ao senhor Serápis»; PGM 13, 706 [com <span class=\"greek\">δέομαι</span>]; Jdt 8:25; 2Mc 1:11; 10:7; 3Mc 7:16; EpArist 177 <span class=\"greek\">ὑμῖν</span>, … <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span>; Fílon, Spec. Leg. 2, 204; 3, 6 <span class=\"greek\">θεῷ</span>; TestSol 7:4; Josefo, Ant. 1, 193 <span class=\"greek\">τ</span>. <span class=\"greek\">θεῷ</span>; TestJos 8:5 <span class=\"greek\">τῷ</span> <span class=\"greek\">κυρίω</span>; TestAbr A 15, p. 95, 14 [Stone p. 38]; Ar. 15, 10 e outros; Justino, Orígenes, Hipólito, Dídimo).</p><p class=\"entry-text\">A abreviação <span class=\"greek\">εὐ</span>. designa o verbo neste grupo de testemunhos. <strong>Com destinatário <span class=\"greek\">αὐτῷ</span>, «a ele»</strong>, referente a Jesus revelando-se como Deus num milagre, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 17:16</a>. <strong>Com <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span> (<span class=\"greek\">μου</span>), «ao (meu) Deus»:</strong> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.15\" target=\"_blank\" rel=\"noopener noreferrer\">At 28:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.25\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 7:25</a>, variante; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.18\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 14:18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 1:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 1:3</a>, 12; 3:17; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHM.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">Fm 4</a>; 1Cl 38:4; 41:1, variante; B 7:1; IEph 21:1; Hv 4, 1, 4. <span class=\"greek\">εὐχαριστῶ</span> <span class=\"greek\">σοι</span>, «agradeço-te», a Deus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 18:11</a> (cf. 1QH 2:20 e outros, אוֹדְכָה אֲדוֹנָי, «eu te louvo, Senhor»). <strong>Uso elíptico</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.21\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 1:21</a>, em que <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span> se subentende do anterior <span class=\"greek\">ὡς</span> <span class=\"greek\">θεόν</span>; excepcionalmente, <span class=\"greek\">εὐχαριστέω</span> ocorre também com acusativo no sentido de «louvar alguém com agradecimento» (SIG 1172, 3 <span class=\"greek\">εὐχαριστεῖ</span> <span class=\"greek\">Ἀσκληπιόν</span>; Cat. Cod. Astr. VII 177, 17). Igualmente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.18\" target=\"_blank\" rel=\"noopener noreferrer\">1Ts 5:18</a>; 2Cl 18:1.</p><p class=\"entry-text\"><strong>Especialmente da ação de graças antes das refeições:</strong> com dativo <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.35\" target=\"_blank\" rel=\"noopener noreferrer\">At 27:35</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.14.6\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 14:6</a> (cf. Ar. 15, 10); <span class=\"greek\">σοι</span>, D 10:3; <span class=\"greek\">ᾧ</span>, B 7:1. <strong>Uso absoluto:</strong> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.36\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:36</a>; 26:27; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 8:6</a>, 7 (variante); 14:23; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.17\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 22:17</a>, 19; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.11\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 6:11</a>, 23; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.24\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 11:24</a> (cf. Justino, A I, 65, 5).</p><p class=\"entry-text\"><strong>Expressão da matéria pela qual se agradece:</strong> <span class=\"greek\">τινί</span> <span class=\"greek\">τι</span>, «a alguém por alguma coisa», Hs 7:5 (<span class=\"greek\">εὐ</span>. <span class=\"greek\">τι</span>, «dar graças por algo», é raro; Hipócrates, Ep. 17, 46; ver <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 1:11</a> abaixo; cf. Justino, A I, 65, 5 <span class=\"greek\">τοῦ</span> <span class=\"greek\">εὐχαριστηθέντος</span> <span class=\"greek\">ἄρτου</span>, «do pão pelo qual se deram graças»). <strong>Com <span class=\"greek\">περί</span> <span class=\"greek\">τινος</span></strong>, «por alguém, por causa de alguém» (Fílon, Spec. Leg. 1, 211), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">1Ts 1:2</a>; «por algo», Hs 5, 1, 1; também seguido de <span class=\"greek\">ὅτι</span>, «porque» (Ps.-Calístenes 2, 22, 11; papiro de Berlim em APF 12 [1937], 247; TestAbr A 15, p. 95, 14 [Stone p. 38]), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 1:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 1:4</a>s.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">2Ts 1:3</a>; 2:13.</p><p class=\"entry-text\"><strong>Com <span class=\"greek\">ὑπέρ</span> <span class=\"greek\">τινος</span> e genitivo de pessoa</strong>, «por alguém em cujo favor se agradece», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 1:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 1:16</a>; Hs 2:6; também seguido de <span class=\"greek\">ὅτι</span>, «porque», IPhld 11:1; ISm 10:1. <strong>Com <span class=\"greek\">ὑπέρ</span> <span class=\"greek\">τινος</span> e genitivo de coisa</strong>, «por algo» (Fílon, Congr. Erud. Gr. 96), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.30\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 10:30</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 5:20</a>; D 9:2s.; 10:2. <strong>Com <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινι</span></strong>, «por causa de; por» (IPergamon 224a, 14; Sb 7172, 25 [217 a.C.] <span class=\"greek\">εὐχαριστῶν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">θεοῖς</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">συντελέσαι</span> <span class=\"greek\">αὐτοὺς</span> <span class=\"greek\">ἃ</span> <span class=\"greek\">ἐπηγγείλαντο</span> <span class=\"greek\">αὐτῷ</span>, «agradecendo aos deuses por terem cumprido o que lhe prometeram»; UPZ 59, 10s. [168 a.C.]; Fílon, Spec. Leg. 1, 67; TestGad 7:6, variante <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">πᾶσι</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">κυρίῳ</span>; Josefo, Ant. 1, 193), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 1:4</a>; Hs 9, 14, 3.</p><p class=\"entry-text\"><strong>Com dativo (<span class=\"greek\">τινί</span>) e oração introduzida por <span class=\"greek\">ὅτι</span></strong>, «porque»: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 18:11</a> (cf. 1QH 2:20); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.41\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 11:41</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 1:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">1Ts 2:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 11:17</a>; 1Cl 38:2; IPhld 6:3; D 10:3, 4. <strong>Com acusativo do conteúdo:</strong> <span class=\"greek\">εὐχαριστεῖν</span> <span class=\"greek\">ὅσα</span> <span class=\"greek\">θέλουσιν</span>, «fazer a oração de ação de graças com tantas palavras quantas desejarem os profetas», D 10:7.</p><p class=\"entry-text\"><strong>Uso absoluto em contexto litúrgico:</strong> <span class=\"greek\">σὺ</span> <span class=\"greek\">εὐχαριστεῖς</span>, «tu proferes uma oração de ação de graças», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.17\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 14:17</a>; com jogo de palavras, «celebrar a Eucaristia»: <span class=\"greek\">οὕτως</span> <span class=\"greek\">εὐχαριστήσατε</span>, «assim dareis graças», D 9:1; <span class=\"greek\">εὐχαριστήσατε</span>, D 14:1; cf. D 10:1. <strong>Expressão parentética:</strong> <span class=\"greek\">εὐχαριστῶ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span>, «graças sejam dadas a Deus», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.18\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 14:18</a>.</p><p class=\"entry-text\"><strong>Voz passiva</strong> (<span class=\"greek\">εὐ</span>. em abreviação; cf. Deissmann, B. 119 [BS 122]; Fílon, Rer. Div. Her. 174 <span class=\"greek\">ἵνα</span> <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἀγαθῶν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">εὐχαριστῆται</span>): <span class=\"greek\">ἵνα</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">πολλῶν</span> <span class=\"greek\">προσώπων</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ἡμᾶς</span> <span class=\"greek\">χάρισμα</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">πολλῶν</span> <span class=\"greek\">εὐχαριστηθῇ</span> <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">ἡμῶν</span>, «para que muitos deem graças em nosso favor pelo benefício concedido a nós», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 1:11</a> (sobre <span class=\"greek\">εὐ</span>. <span class=\"greek\">τι</span>, ver acima). Bibliografia específica: P. Schubert, <em>Form and Function of the Pauline Thanksgivings</em> (1939).</p><p class=\"entry-text\">③ <strong>Orar, em sentido geral</strong>, interpretação possível em algumas passagens (PTebt 56, 9 [séc. II a.C.] <span class=\"greek\">εὐχαριστῆσαι</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">θεοῖς</span>; PLond II, 413, 3, p. 301; II, 418, 3, p. 303 [ambos documentos cristãos, cerca de 346 d.C.]; BGU 954, 4). 1Cl 62:2, variante de leitura em lugar de <span class=\"greek\">εὐαριστεῖν</span>.</p><p class=\"entry-text\"><strong>Bibliografia geral:</strong> F. Hort, «<span class=\"greek\">Εὐχαριστία</span>, <span class=\"greek\">εὐχαριστεῖν</span> (in Philo)», JTS 3 (1902), 594–98; T. Schermann, «<span class=\"greek\">Εὐχαριστία</span> and <span class=\"greek\">εὐχαριστεῖν</span>», Philol 69 (1910), 375–410; G. Boobyer, <em>Thanksgiving and the Glory of God in Paul</em>, tese, Heidelberg (1929); J. M. Robinson, «Die Hodajot-Formel in Gebet und Hymnus des Frühchristentums», em <em>Apophoreta</em> (Festschrift E. Haenchen) (1964), 194–235; H. Patsch, ZNW 62 (1971), 210–31; RAC VI 900–928; B. 1166; DELG, s.v. <span class=\"greek\">χάρις</span>; <em>New Docs</em> 127–29; M-M; EDNT; TW.</p></section></article>\n<article id=\"entry-eucharistia-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐχαριστία, ας, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eucharistía⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">εὐχαριστία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span>. Ver o verbete precedente. Desde Hipócrates, Comp. II 87s.; Ps.-Menandro, Fgm. 693 Kock; inscrições; PLond III, 1178, 25, p. 216 [194 d.C.]; LXX; Fílon; Josefo; Justino; Didaquê.</p><p class=\"entry-text\">① <strong>Qualidade de quem é agradecido, com atitude apropriada: gratidão; reconhecimento</strong> (elemento importante na reciprocidade greco-romana; comparar os decretos dos bizantinos em Demóstenes 18, 91, citados em <span class=\"greek\">εὐχαριστέω</span> ①; Políbio 8, 12, 8; Diodoro Sículo 17, 59, 7; OGI 227, 6; 199, 31 [séc. I d.C.] <span class=\"greek\">ἔχω</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">μέγιστον</span> <span class=\"greek\">θεόν</span> <span class=\"greek\">μου</span> <span class=\"greek\">Ἄρην</span> <span class=\"greek\">εὐχαριστίαν</span>, «tenho gratidão para com o meu grande deus Ares»; BGU 1764, 21 [séc. I a.C.]; 2Mc 2:27; Est 8:12d; Fílon, Leg. All. 1, 84). <span class=\"greek\">μετὰ</span> <span class=\"greek\">πάσης</span> <span class=\"greek\">εὐ</span>., «com toda a gratidão» (cf. Orígenes, C. Cels. 7, 46, 8), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.3\" target=\"_blank\" rel=\"noopener noreferrer\">At 24:3</a>.</p><p class=\"entry-text\">② <strong>Expressão ou conteúdo da gratidão: agradecimento; ação de graças</strong> (SIG 798, 5 [cerca de 37 d.C.] <span class=\"greek\">εἰς</span> <span class=\"greek\">εὐχαριστίαν</span> <span class=\"greek\">τηλικούτου</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">εὑρεῖν</span> <span class=\"greek\">ἴσας</span> <span class=\"greek\">ἀμοιβάς</span>, «encontrar retribuições equivalentes em ação de graças a tão grande deus»; Wsd 16:28; Sir 37:11; Fílon, Spec. Leg. 1, 224; Josefo, Ant. 1, 156; 2, 346; 3, 65; 4, 212). <strong>Uso absoluto</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 5:4</a> (O. Casel, BZ 18 [1929], 84s., seguindo Orígenes, equipara <span class=\"greek\">εὐχαριστία</span> a <span class=\"greek\">εὐχαριτία</span>, «sinal de boa educação»). <strong>Com <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span></strong>, «a Deus», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.9.11\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 9:11</a>. <span class=\"greek\">μετὰ</span> <span class=\"greek\">εὐχαριστίας</span>, «com ação de graças» (Fílon, Spec. Leg. 1, 144), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 4:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 4:3</a>s.; <span class=\"greek\">ἐν</span> <span class=\"greek\">εὐ</span>., «em ação de graças», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 4:2</a>.</p><p class=\"entry-text\"><span class=\"greek\">περισσεύειν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">εὐ</span>., «transbordar em ações de graças», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 2:7</a>; <span class=\"greek\">περισσεύειν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">εὐ</span>., «fazer crescer a ação de graças», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.4.15\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 4:15</a>. <span class=\"greek\">εὐχαριστίαν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span> <span class=\"greek\">ἀνταποδοῦναι</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">ὑμῶν</span>, «retribuir a Deus ações de graças por vós», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">1Ts 3:9</a>. <span class=\"greek\">εὐ</span>. <span class=\"greek\">διδόναι</span>, «dar graças» (Teodoro Pródromo 8, 414 H., <span class=\"greek\">θεοῖς</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.4.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 4:9</a>.</p><p class=\"entry-text\"><strong>Especialmente oração de ação de graças</strong> (Herm. Wr. 1, 29), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.16\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 14:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.7.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 7:12</a>. <strong>Plural</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.9.12\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 9:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 2:1</a>.</p><p class=\"entry-text\">③ <strong>Celebração e elementos da Eucaristia, isto é, da Ceia do Senhor: Eucaristia.</strong> <span class=\"greek\">ποτήριον</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">εὐχ</span>., «cálice da Eucaristia», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.16\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 10:16</a>, variante textual. D 9:1, 5 (J. Clabeaux, em <em>Prayers from Alexander to Constantine</em>, ed. M. Kiley [1997], 260–66); IEph 13:1; IPhld 4; ISm 8:1. Associado a <span class=\"greek\">προσευχή</span>, «oração», ISm 7:1. Cf. Justino, A I, 65, 3; 66, 1; Orígenes, C. Cels. 57, 20; R. Knopf, <em>Handbuch</em>, comentário a D 9:1.</p><p class=\"entry-text\"><strong>Bibliografia para a Ceia do Senhor e a Eucaristia:</strong> J. Réville, <em>Les origines de l’Eucharistie</em> (1908); M. Goguel, <em>L’Eucharistie des origines à Justin martyr</em> (1909); F. Wieland, <em>Der vorirenäische Opferbegriff</em> (1909); G. Loeschcke, «Zur Frage nach der Einsetzung u. Herkunft der Eucharistie», ZWT 54 (1912), 193–205; A. Loisy, «Les origines de la Cène eucharistique», <em>Congrès d’Histoire du Christianisme</em> I (1928), 77–95; G. MacGregor, <em>Eucharistic Origins</em> (1929); K. Goetz, <em>Der Ursprung des kirchlichen Abendmahls</em> (1929); H. Huber, <em>Das Herrenmahl im NT</em>, tese, Berna (1929); W. Goossens, <em>Les origines de l’Eucharistie</em> (1931); R. Hupfeld, <em>Die Abendmahlsfeier, ihr ursprünglicher Sinn usw.</em> (1935); J. Jeremias, <em>Die Abendmahlsworte Jesu</em>, 1935, 2.ª ed. 1949, 3.ª ed. 1960 (tradução inglesa <em>The Eucharistic Words of Jesus</em>, A. Ehrhardt, 1955; ver K. Kuhn, TLZ 75 [1950], 399–408); J. Jeremias, «Das paulinische Abendmahl—eine Opferdarbietung?», StKr 108 (1937), 124–41; A. Arnold, <em>Der Ursprung des christlichen Abendmahls</em> (1937; 2.ª ed. 1939); L. Poot, <em>Het oudchristelijk Avondmaal</em> (1936); E. Lohmeyer, «Das Abendmahl in der Urgemeinde», JBL 56 (1937), 217–52; E. Käsemann, «Das Abendmahl im NT: Abendmahlsgemeinschaft?», (1937), 60–93; H. Sasse, «Das Abendmahl im NT», em <em>Vom Sakrament des Altars</em> (1941), 26–78; E. Gaugler, <em>Das Abendmahl im NT</em> (1943); N. Johansson, <em>Det urkristna nattvardsfirandet</em> (1944).</p><p class=\"entry-text\"><strong>Bibliografia complementar:</strong> E. Schweizer, «Das Abendmahl: eine Vergegenwärtigung des Todes Jesu oder ein eschatologisches Freudenmahl?», TZ 2 (1946), 81–101; T. Preiss, TZ 4 (1948), 81–101 (tradução inglesa «Was the Last Supper a Paschal Meal?», em <em>Life in Christ</em>, cap. 5 [1954], 81–99); F.-J. Leenhardt, <em>Le Sacrement de la Sainte Cène</em> (1948); G. Walther, <em>Jesus, das Passalamm des Neuen Bundes</em> (1950); R. Bultmann, <em>Theology of the New Testament</em>, tradução K. Grobel (1951), I, 144–52; A. Higgins, <em>The Lord's Supper in the NT</em> (1952); O. Cullmann, <em>Early Christian Worship</em>, tradutores A. Todd e J. Torrance (1953); H. Lessig, <em>Die Abendmahlsprobleme im Lichte der NTlichen Forschung seit 1900</em>, tese, Bonn (1953); E. Schweizer, TLZ 79 (1954), 577–92 [bibliografia]; G. Bornkamm, «Herrenmahl und Kirche bei Paulus», NTS 2 (1955/56), 202–6; C. Moule, «The Judgment Theme in the Sacraments», em <em>Background of the NT and Its Eschatology</em> (Festschrift C. Dodd) (1956), 464–81.</p><p class=\"entry-text\"><strong>Bibliografia posterior:</strong> M. Black, «The Arrest and Trial of Jesus and the Date of the Last Supper», em <em>NT Essays</em> (volume memorial T. Manson) (1959), 19–33; P. Neuenzeit, <em>Das Herrenmahl</em> (1960); <em>The Eucharist in the NT</em>, cinco ensaios traduzidos do francês por E. Stewart (1964); E. Kilmartin, <em>The Eucharist in the Primitive Church</em> (1965); B. Iersel, NovT 7 (1964/65), 167–94; H. Braun, <em>Qumran</em> II (1966), 29–54; J. Audet, TU 73 (1959), 643–62; H. Schürmann, <em>Der Paschamahlbericht</em> (1953), <em>Der Einsetzungsbericht</em> (1955), <em>Jesu Abschiedsrede</em> (1957), todos relativos a Lc 22; H. Patsch, <em>Abendmahl und Historischer Jesus</em> (1972); F. Hahn, RGG⁴ I, 10–15 [NT]; C. Markschies, ibid., 15–21 [igreja primitiva]. Ver também a bibliografia em <span class=\"greek\">ἀγάπη</span> ②. Bibliografia lexicográfica: M-M; TW.</p></section></article>\n<article id=\"entry-eucharistos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐχάριστος, ον</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eucháristos⟧</span><span class=\"separator\">·</span><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">εὐχάριστος</span>, <span class=\"greek\">ον</span>. Ver os dois verbetes precedentes. Heródoto e posteriores; inscrições, papiros; Pv 11:16; Fílon. <strong>Que manifesta gratidão: agradecido; grato</strong> (comparar a acepção primária de <span class=\"greek\">εὐχαριστέω</span> e <span class=\"greek\">εὐχαριστία</span>; Xenofonte, Cyr. 8, 3, 49; OGI 267, 36; 339, 60 e numerosas inscrições de cidades e cidadãos gratos a seus benfeitores; Josefo, Ant. 16, 162; Ar. [Milne 76, 49]). <span class=\"greek\">εὐχάριστοι</span> <span class=\"greek\">γίνεσθε</span>, «sede agradecidos», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.15\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 3:15</a> (IPriene 103, 8 [cerca de 100 a.C.] <span class=\"greek\">γενόμενος</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">δῆμος</span> <span class=\"greek\">εὐ</span>., «tendo o povo se mostrado agradecido»; Fílon, Spec. Leg. 2, 209; Justino, A I, 13, 2 <span class=\"greek\">εὐ</span>. <span class=\"greek\">ὄντας</span>). Bibliografia: M-M; TW.</p></section></article>\n<article id=\"entry-eucheres-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐχερής, ές,</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eucherḗs⟧</span><span class=\"separator\">·</span><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">εὐχερής</span>, <span class=\"greek\">ές</span>; genitivo <span class=\"greek\">ους</span>. Ver <span class=\"greek\">χείρ</span>. Sófocles, Hipócrates e posteriores; inscrições; UPZ 162 VIII, 13 [117 a.C.] <span class=\"greek\">εὐχερῶς</span>; LXX.</p><p class=\"entry-text\">① <strong>Que tende ou se inclina a algo, com relativa ausência de contenção: facilmente inclinado; propenso; precipitado; temerário</strong> (Demóstenes 21, 103; Aristóteles, Metaph. 1025a, 2; PGM 4, 2504 <span class=\"greek\">εὐχερῶς</span>; Fílon, Somn. 1, 13; Josefo, Vi. 167; Justino, D. 20, 1; 67, 8 com <span class=\"greek\">πρός</span>; A II, 2, 7 <span class=\"greek\">εὐχερῶς</span>). <span class=\"greek\">ἐν</span> <span class=\"greek\">καταλαλιᾷ</span>, «propenso à maledicência», B 20:2.</p><p class=\"entry-text\">② <strong>Que exige pouco esforço: fácil.</strong> <span class=\"greek\">εὐχερές</span> <span class=\"greek\">ἐστιν</span>, seguido de infinitivo, «é fácil» (Batr. 62; SIG 674, 65; Jdt 7:10); <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">εὐχερές</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">ποιῆσαι</span>, «é fácil para vós fazer», IRo 1:2. Bibliografia: DELG, s.v. <span class=\"greek\">χείρ</span>.</p></section></article>\n<article id=\"entry-euche-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐχή, ῆς, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦euchḗ⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">εὐχή</span>, <span class=\"greek\">ῆς</span>, <span class=\"greek\">ἡ</span>. Ver <span class=\"greek\">εὔχομαι</span>. Homero e posteriores; Melitão, HE 4, 26, 8, «desejo».</p><p class=\"entry-text\">① <strong>Fala ou petição dirigida a Deus: oração</strong> (Xenofonte, Symp. 8, 15; Diodoro Sículo 20, 50, 6 <span class=\"greek\">εὐχὰς</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">θεοῖς</span> <span class=\"greek\">ἐποιοῦντο</span>, «faziam orações aos deuses»; Dião Crisóstomo 19 [36], 36; OGI 383, 233 [séc. I a.C.]; BGU 531 I, 5 [séc. I d.C.]; PGiss 23, 5 [séc. II d.C.]; LXX; TestAbr A; TestJob; Test12Patr; ParJer 9:3; GrBar 4:14; Fílon, Sacr. Abel. 53 e frequentemente [sobre Fílon, C. Larson, JBL 65 (1946), 185–203]; Josefo, Bell. 7, 155; Ant. 15, 52; Justino, Irineu, Orígenes). <span class=\"greek\">ἡ</span> <span class=\"greek\">εὐ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">πίστεως</span>, «a oração feita com fé», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.15\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 5:15</a>. <span class=\"greek\">πληρῶσαι</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">εὐ</span>., «terminar uma oração», MPol 15:1; também <span class=\"greek\">τελέσας</span> … <span class=\"greek\">τὴν</span> <span class=\"greek\">εὐ</span>., GJs 9:1. <span class=\"greek\">μου</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">εὐ</span>., «minha oração», GJs 1:4. <span class=\"greek\">ἐν</span> <span class=\"greek\">εὐχῇ</span>, «em oração», GJs 24:1 (variante <span class=\"greek\">εὐχαῖς</span>). Plural em D 15:4. <span class=\"greek\">νήφειν</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">εὐ</span>., «manter-se vigilante nas orações», Pol 7:2.</p><p class=\"entry-text\">② <strong>Promessa solene cujo inadimplemento implica sanção: voto</strong> (Xenofonte, Mem. 2, 2, 10; Diodoro Sículo 1, 83, 2; Josefo, Bell. 2, 313), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.18\" target=\"_blank\" rel=\"noopener noreferrer\">At 18:18</a>; 21:23 (J. Ubbink, NThSt 5 [1922], 137–39). <span class=\"greek\">θυσίαι</span> <span class=\"greek\">εὐχῶν</span>, «sacrifícios votivos» (cf. Lv 22:29; Diodoro Sículo 3, 55, 8, <span class=\"greek\">θυσίαι</span> resultantes de <span class=\"greek\">εὐχαί</span>), 1Cl 41:2. <span class=\"greek\">ἀποδιδόναι</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ὑψίστῳ</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">εὐ</span>., «cumprir os votos ao Altíssimo» (ver <span class=\"greek\">ἀποδίδωμι</span> 2c), 1Cl 52:3 (Sl 49:14). Bibliografia: A. Wendel, <em>D. israel.-jüd. Gelübde</em> (1931); H. Salmanowitsch, <em>D. Nasiräat nach Bibel u. Talmud</em>, tese, Giessen (1931); H. Gowen, «The Hair-Offering», JSOR 11 (1927), 1–20; RAC VIII 1134–1258; IX 1–36; DELG, s.v. <span class=\"greek\">εὔχομαι</span>; M-M; TW; Spicq.</p></section></article>\n<article id=\"entry-euchomai-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔχομαι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eúchomai⟧</span><span class=\"separator\">·</span><span>verbo depoente</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">εὔχομαι</span>. Imperfeito <span class=\"greek\">εὐχόμην</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.29\" target=\"_blank\" rel=\"noopener noreferrer\">At 27:29</a> (Tischendorf; ver Proleg., p. 121); e <span class=\"greek\">ηὐχόμην</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.3\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 9:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.29\" target=\"_blank\" rel=\"noopener noreferrer\">At 27:29</a>. Futuro <span class=\"greek\">εὔξομαι</span> na LXX; primeiro aoristo <span class=\"greek\">εὐξάμην</span> (também <span class=\"greek\">ηὐ</span>- na LXX); particípio perfeito <span class=\"greek\">ηὐγμένος</span>, Nm 6:20. Ver o verbete precedente. Homero e posteriores.</p><p class=\"entry-text\">① <strong>Falar a Deus ou dirigir-lhe petições: orar.</strong> Uso absoluto (LXX; TestSol 26:8; A 5, p. 81, 33; Justino, D. 90, 5; 103, 8). <strong>Com dativo <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span></strong>, «a Deus» (Homero; Tucídides 3, 58, 5; Xenofonte, Cyr. 7, 1, 1; Plutarco, Pericl. 156 [8, 6]; Epicteto 1, 29, 37; OGI 219, 21; POxy 1298, 4; PRyl 244, 3; Sir 38:9; ApcMos 5:31; Fílon, Ebr. 125; Josefo, Ant. 14, 22; 18, 211; Justino, D. 1:4; Orígenes, C. Cels. 8, 37, 12 e outros; sobre <span class=\"greek\">εὔχ</span>. <span class=\"greek\">τ</span>. <span class=\"greek\">θεοῖς</span>, ver G. Ghedini, Aegyptus 2 [1921], 191ss.), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.29\" target=\"_blank\" rel=\"noopener noreferrer\">At 26:29</a>; IRo 1:1.</p><p class=\"entry-text\"><strong>Com <span class=\"greek\">πρὸς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεόν</span>, «a Deus»</strong> (Xenofonte, Mem. 1, 3, 2; Symp. 4, 55; 2Mc 9:13; 15:27; TestSol 18:42; EpArist 305), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.13.7\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 13:7</a>.</p><p class=\"entry-text\"><strong>Objeto do pedido:</strong> acusativo simples, «pedir algo» (Píndaro e outros; Josefo, Ant. 12, 98), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.13.9\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 13:9</a>; acusativo seguido de infinitivo (Homero e outros; TestSol 18:42; Dídimo, Gen. 73, 10), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.29\" target=\"_blank\" rel=\"noopener noreferrer\">At 26:29</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.13.7\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 13:7</a>; ou construções preposicionais: <span class=\"greek\">εὐ</span>. <span class=\"greek\">περί</span> <span class=\"greek\">τινος</span>, «orar a respeito de alguém», GJs 8:3; 13:1; <span class=\"greek\">εὐ</span>. <span class=\"greek\">περί</span> <span class=\"greek\">τινος</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">κύριον</span>, «orar ao Senhor por alguém», Hs 5, 3, 7.</p><p class=\"entry-text\"><strong>Com <span class=\"greek\">εὐ</span>. <span class=\"greek\">ὑπέρ</span> <span class=\"greek\">τινος</span>, «orar em favor de alguém»</strong> (Xenofonte, Mem. 2, 2, 10; Ésquines 3:18 <span class=\"greek\">ὑπέρ</span> <span class=\"greek\">τινος</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">θεούς</span>; Longo 2, 24, 2; Diógenes Laércio 8, 9 <span class=\"greek\">εὔ</span>. <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">ἑαυτῶν</span>; PMeyer 24, 4; TestGad 7:1; TestJos 18:2; ParJer 2:3; ApcMos 35; Josefo, Ant. 11, 119; Justino, D. 96, 3 e outros). Seguido de <span class=\"greek\">ὅπως</span>, «para que» (ParJer 2:3 [códice C]; Epicteto 2, 16, 13; Polieno 1, 26 <span class=\"greek\">εὐ</span>. <span class=\"greek\">Διὶ</span> <span class=\"greek\">ὅπως</span>; PRyl 244, 3 <span class=\"greek\">εὔχομαι</span> <span class=\"greek\">θεοῖς</span> <span class=\"greek\">πᾶσιν</span> <span class=\"greek\">ὅπως</span> <span class=\"greek\">ὑγιαίνοντας</span> <span class=\"greek\">ὑμᾶς</span> <span class=\"greek\">ἀπολάβω</span>, «oro a todos os deuses para que vos reencontre com saúde»; Josefo, Ant. 11, 17), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.16\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 5:16</a>; ou seguido de <span class=\"greek\">ἵνα</span>, «para que» (Dionísio de Halicarnasso 9, 53; Epicteto 2, 6, 12; EpArist 45; Justino, D. 35, 8), Hs 5, 2, 10. Bibliografia desta acepção: ver o final de <span class=\"greek\">προσεύχομαι</span>.</p><p class=\"entry-text\">② <strong>Desejar</strong> (Píndaro e outros; inscrições, papiros, Fílon; talvez Josefo, Ant. 12, 98; cf. Melitão, HE 4, 26, 8: <span class=\"greek\">εὐχή</span> = «desejo»). <strong>Com acusativo <span class=\"greek\">τὶ</span></strong>, «desejar algo» (Xenofonte, Hell. 5, 1, 3), IMg 1:2. <strong>Seguido de infinitivo</strong> (<span class=\"greek\">Περὶ</span> <span class=\"greek\">ὕψους</span> 9, 10; inscrição de Alexandria em U. von Wilamowitz, SBBerlAk [1902], 1098: <span class=\"greek\">εὔχομαι</span> <span class=\"greek\">κἀγὼ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τάχυ</span> <span class=\"greek\">σὺν</span> <span class=\"greek\">σοὶ</span> <span class=\"greek\">εἶναι</span>, «também desejo estar contigo em breve»; SibOr 4, 111; Justino, A I, 15, 6), ITr 10:1.</p><p class=\"entry-text\"><strong>Seguido de acusativo e infinitivo</strong> (Xenofonte, An. 1, 4, 7; Ep. 46 de Apolônio de Tiana em Filóstrato I 355, 24 K.; Justino, D. 79, 2 e outros), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.29\" target=\"_blank\" rel=\"noopener noreferrer\">At 27:29</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/3JN.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">3Jo 2</a> (cf. POxy 292, 11 [talvez 25 d.C.] <span class=\"greek\">πρὸ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">πάντων</span> <span class=\"greek\">ὑγιαίνειν</span> <span class=\"greek\">σε</span> <span class=\"greek\">εὔχομαι</span>, «acima de tudo, desejo que tenhas saúde»; PFay 117, 27; PMich 203, 2); IEph 1:3; 2:1; ITr 12:3; IRo 5:2; ISm 11:1; 13:2; IPol 8:3; MPol 22:1. <strong>Seguido de nominativo e infinitivo</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.3\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 9:3</a>, por analogia com <span class=\"greek\">θέλω</span> mais infinitivo (cf. Ésquilo, Eum. 429; TestReub 1:7), equivalente ao optativo com <span class=\"greek\">ἄν</span>. <strong>Seguido de <span class=\"greek\">ἵνα</span> <span class=\"greek\">μή</span></strong>, IPhld 6:3. <strong>Fórmula de saudação:</strong> <span class=\"greek\">εὐ</span>. <span class=\"greek\">πλεῖστα</span> <span class=\"greek\">χαίρειν</span>, «desejo muita alegria», IMg, inscrição; ITr, inscrição.</p><p class=\"entry-text\">Bibliografia: A. Adkins, ClQ 19 (1969), 20–33, sobre Homero; M-M; EDNT; TW; Spicq; Sv.</p></section></article>\n<article id=\"entry-euchrestos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὔχρηστος, ον</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eúchrēstos⟧</span><span class=\"separator\">·</span><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">εὔχρηστος</span>, <span class=\"greek\">ον</span>. Ver <span class=\"greek\">χρηστός</span> (a grafia da remissão no testemunho consultado é <span class=\"greek\">χηρηστός</span>); Hipócrates e posteriores; inscrições, papiros, LXX; EpArist 136; Josefo; Melitão, P. 94, 723. <strong>Que presta auxílio ou benefício: útil; proveitoso; prestativo</strong>, termo comum no mundo greco-romano para designar serviço socialmente valioso.</p><p class=\"entry-text\"><strong>Uso absoluto</strong> (<span class=\"greek\">εὔ</span>., abreviação do adjetivo no original), em contraste com <span class=\"greek\">ἄχρηστος</span>, «inútil», Hv 3, 6, 7. <strong>Acerca de ouro</strong>, Hv 4, 3, 4. <strong>Com dativo <span class=\"greek\">τινί</span>, «útil a alguém ou a alguma coisa»:</strong> com pessoa (PPetr III, 53 [n], 5), <span class=\"greek\">σκεῦος</span> <span class=\"greek\">εὔ</span>. <span class=\"greek\">τ</span>. <span class=\"greek\">δεσπότῃ</span>, «vaso útil ao senhor», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.21\" target=\"_blank\" rel=\"noopener noreferrer\">2Tm 2:21</a>. <strong>Jogo de palavras com Onésimo</strong>, em contraste com <span class=\"greek\">ἄχρηστος</span>: <span class=\"greek\">σοὶ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἐμοὶ</span> <span class=\"greek\">εὔ</span>., «útil para ti e para mim», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHM.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">Fm 11</a>; cf. Hv 3, 6, 6b; Hm 5, 1, 6; Hs 9, 26, 4.</p><p class=\"entry-text\"><strong>De membros do corpo:</strong> <span class=\"greek\">εὔ</span>. <span class=\"greek\">ὅλῳ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">σώματι</span>, «úteis ao corpo inteiro», 1Cl 37:5. <span class=\"greek\">εὔ</span>. <span class=\"greek\">γίνεσθαι</span>, com dativo de pessoa, «tornar-se útil» (IPriene 102, 5 [c. 100 a.C.] <span class=\"greek\">προγόνων</span> <span class=\"greek\">γεγενημένων</span> <span class=\"greek\">εὐχρήστων</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">δήμῳ</span>), Hv 3, 6, 6c; 7b; Hm 5, 1, 5; Hs 9, 15, 6. <strong>Com <span class=\"greek\">εἴς</span> <span class=\"greek\">τι</span>, «útil para determinada finalidade»</strong> (Diodoro Sículo 5, 40, 1; IGR IV, 818, 23 <span class=\"greek\">εἰς</span> <span class=\"greek\">χρίας</span> <span class=\"greek\">κυριακὰς</span> <span class=\"greek\">εὔχρηστον</span> <span class=\"greek\">γενόμενον</span>, «tendo-se tornado útil às necessidades do senhor»; Wsd 13:13; Josefo, Ant. 4, 281), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">2Tm 4:11</a>; Hv 3, 5, 5; 3, 6, 1; 6a. Bibliografia: DELG, s.v. <span class=\"greek\">χρή</span>; Larfeld I 497; M-M.</p></section></article>\n<article id=\"entry-eupsycheo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐψυχέω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦eupsychéō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">εὐψυχέω</span>. Ver <span class=\"greek\">ψυχή</span>. BGU 1097, 15 [séc. I d.C.] <span class=\"greek\">ἐγὼ</span> <span class=\"greek\">εὐψυχοῦσα</span> <span class=\"greek\">παραμένω</span>, «eu permaneço com bom ânimo»; POxy 115, 1; Pólux 3, 28, 135; Josefo, Ant. 11, 241. <strong>Ser animado; alegrar-se; ter coragem</strong>: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.19\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 2:19</a>, com implicação de libertação da ansiedade. Imperativo <span class=\"greek\">εὐψύχει</span>, «tem coragem» (em inscrições tumulares, com o sentido de «adeus»: CIG 4467, frequentemente em Sb, II, lista geral de palavras, p. 404): Hv 1, 3, 2. Bibliografia: DELG, s.v. <span class=\"greek\">ψυχή</span>; M-M; TW; Spicq.</p></section></article>\n<article id=\"entry-euodia-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐωδία, ας, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦euōdía⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">εὐωδία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span>. Ver <span class=\"greek\">ὄζω</span>; Xenofonte, Platão e posteriores; LXX; pseudepígrafos; Fílon; Atenágoras 13, 1. <strong>Aroma; fragrância; bom perfume</strong>. <span class=\"greek\">ὀσμὴ</span> <span class=\"greek\">εὐωδίας</span> (= hebraico רֵיחַ הַנִּיחוֹחַ, Gn 8:21; Êx 29:18 e outros, do aroma de sacrifício que agrada a Deus), «odor fragrante», com <span class=\"greek\">θυσία</span> (TestLevi 3:6), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.18\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 4:18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 5:2</a>; B 2:10.</p><p class=\"entry-text\"><strong>A respeito dos apóstolos</strong>, <span class=\"greek\">Χριστοῦ</span> <span class=\"greek\">εὐ</span>. <span class=\"greek\">ἐσμὲν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span>, «somos para Deus o bom perfume de Cristo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 2:15</a> (cf. <span class=\"greek\">ἐν</span> <span class=\"greek\">εὐωδίᾳ</span> <span class=\"greek\">χρηστότητος</span> <span class=\"greek\">κυρίου</span>, «na fragrância da bondade do Senhor», OdeSol 11:15). Quando Policarpo foi queimado, observou-se uma fragrância, MPol 15:2 (cf. Diodoro Sículo 3, 46, 4 <span class=\"greek\">θεία</span> <span class=\"greek\">εὐωδία</span>, «fragrância divina», <span class=\"greek\">κτλ</span>., «etc.»).</p><p class=\"entry-text\">Bibliografia: E. Lohmeyer, «Vom göttl. Wohlgeruch», SBHeidAk (1919), ensaio 9; Reitzenstein, <em>Erlösungsmysterium</em>, 34, 143ss.; <em>Mysterienreligionen</em>, 3.ª ed., 82s., 393ss.; H. Kees, <em>Totenglauben u. Jenseitsvorstellungen d. alt. Ägypter</em> (1926), 148; H. Vorwahl, ARW 31 (1934), 400s.; P. de Boer, <em>Studies in the Religion of Ancient Israel</em> (1972), 37–47 [fragrância]; DELG, s.v. <span class=\"greek\">ὄζω</span>; EDNT; M-M; TW.</p></section></article>\n<article id=\"entry-euonymos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐώνυμος, ον</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦euṓnymos⟧</span><span class=\"separator\">·</span><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">εὐώνυμος</span>, <span class=\"greek\">ον</span>. Ver <span class=\"greek\">ὄνομα</span>. Hesíodo, Píndaro e posteriores. <strong>Como referência espacial oposta ao lado direito: esquerdo; do lado esquerdo</strong> (Ésquilo, Heródoto e outros; SIG 827 III, 9, 16; 1167; PRyl 63, 4; LXX; JosAs; ApcrEzk [Epifânio 70, 10]; Fílon; Josefo, Ant. 12, 429), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.10.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 10:2</a>.</p><p class=\"entry-text\"><span class=\"greek\">καταλιπόντες</span> <span class=\"greek\">αὐτὴν</span> (isto é, <span class=\"greek\">τὴν</span> <span class=\"greek\">Κύπρον</span>) <span class=\"greek\">εὐώνυμον</span>, «deixando-a [Chipre] à esquerda», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.3\" target=\"_blank\" rel=\"noopener noreferrer\">At 21:3</a>. <span class=\"greek\">ἐξ</span> <span class=\"greek\">εὐωνύμων</span>, «à esquerda» (Diodoro Sículo 4, 56, 3; Êx 14:22, 29; 2Cr 4:8 e outros), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20:23</a>; 25:33, 41; 27:38 (cf. 2Cr 3:17); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.40\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 10:40</a>; Hv 3, 2, 4. <span class=\"greek\">ἐξ</span> <span class=\"greek\">εὐωνύμων</span> <span class=\"greek\">τινός</span>, «à esquerda de alguém» (2Km 16:6; 3Km 22:19 e outros), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 15:27</a>. <strong>Uso bastante isolado:</strong> <span class=\"greek\">εὐώνυμα</span>, «à esquerda», contraposto a <span class=\"greek\">δεξιά</span>, «à direita», Hs 9, 12, 8. Bibliografia: B. 866; DELG, s.v. <span class=\"greek\">ὄνομα</span>; M-M.</p></section></article>\n<article id=\"entry-euocheo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐωχέω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦euōchéō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">εὐωχέω</span>. Ver <span class=\"greek\">ἔχω</span>, Boisacq 300 e o verbete seguinte. Heródoto e posteriores; Fílon; Josefo; papiros. Voz média desde Alceu, Fgm. 70, 5 L-P.; Jdt 1:16; 3Mc 6:40; papiros; particípio <span class=\"greek\">εὐωχηθείς</span>, OGI 168, 11.</p><p class=\"entry-text\">Na literatura grega, a <strong>voz ativa</strong> de <span class=\"greek\">ἐ</span>. (abreviação de <span class=\"greek\">εὐωχέω</span>) indica <strong>proporcionar entretenimento suntuoso; oferecer um banquete</strong> (Heródoto e outros). A <strong>voz média</strong> <span class=\"greek\">εὐωχεῖσθαι</span> significa <strong>participar de um banquete; banquetear-se</strong> (Alceu e outros); assim também AcPl Ha 7, 10, provavelmente referente a celebração de ágape após a Eucaristia (ver Schubart, p. 51, nota 10). Para festividades cultuais, IGLSyria 1, 157s. [séc. I a.C.]; H. Dörrie, GGAbh 60 (1964), 81.</p></section></article>\n<article id=\"entry-euochia-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">εὐωχία, ας, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦euōchía⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">εὐωχία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span>. Ver o verbete anterior. Aristófanes, Hipócrates e outros; Diodoro Sículo 2, 26, 4; inscrições, papiros; LXX; TestJob 44:2; Fílon; Josefo, Ant. 6, 163; C. Ap. 2, 138. <strong>Banquete; festim; celebração com refeição</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JUD.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">Jd 12</a>, variante textual.</p></section></article>\n<article id=\"entry-ephagon-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔφαγον</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦éphagon⟧</span><span class=\"separator\">·</span><span>aoristo verbal remissivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἔφαγον</span>. <strong>Ver <span class=\"greek\">ἐσθίω</span>.</strong> Forma verbal remissiva independente no léxico. A fonte não apresenta outras acepções nesta entrada.</p></section></article>\n<article id=\"entry-ephallomai-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐφάλλομαι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦ephállomai⟧</span><span class=\"separator\">·</span><span>verbo depoente</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἐφάλλομαι</span>. Futuro, terceira pessoa do singular <span class=\"greek\">ἐφαλεῖται</span>, 1Km 10:6; segundo aoristo <span class=\"greek\">ἐφαλόμην</span>; terceira pessoa do singular <span class=\"greek\">ἐφήλατο</span>, 1Km 11:6; 16:13. Ver <span class=\"greek\">ἅλλομαι</span>; Homero e posteriores; inscrições, papiros, LXX. <strong>Saltar sobre; lançar-se contra</strong>, com <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινα</span>, «sobre alguém» (1Km 10:6; 16:13, acerca da vinda do Espírito de Deus sobre uma pessoa). A respeito de homem «possesso», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.16\" target=\"_blank\" rel=\"noopener noreferrer\">At 19:16</a>. Bibliografia: DELG, s.v. <span class=\"greek\">ἅλλομαι</span>; M-M.</p></section></article>\n<article id=\"entry-ephapax-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐφάπαξ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦ephápax⟧</span><span class=\"separator\">·</span><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἐφάπαξ</span>. Advérbio, ver <span class=\"greek\">ἅπαξ</span>.</p><p class=\"entry-text\">① <strong>Referente a acontecimentos simultâneos: de uma vez; de uma só vez; ao mesmo tempo</strong> (PLond II, 483, 88, p. 328 [616 d.C.]; V, 1708, 242; PFlor 158, 10). <span class=\"greek\">ἐπάνω</span> <span class=\"greek\">πεντακοσίοις</span> <span class=\"greek\">ἀδελφοῖς</span> <span class=\"greek\">ἐ</span>., «a mais de quinhentos irmãos ao mesmo tempo», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.6\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 15:6</a>.</p><p class=\"entry-text\">② <strong>Realizado uma única vez, excluindo qualquer repetição: uma vez por todas; uma única vez e nunca mais</strong> (Eúpolis Cômico [séc. V a.C.], 175 Kock), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.6.10\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 6:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.27\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:27</a>; 9:12; 10:10. Bibliografia: M-M; TW; Spicq.</p></section></article>\n<article id=\"entry-ephesinos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἐφέσινος, η, ον</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦Ephésinos⟧</span><span class=\"separator\">·</span><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">Ἐφέσινος</span>, <span class=\"greek\">η</span>, <span class=\"greek\">ον</span>. <strong>Efésino; relativo a Éfeso</strong>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 2:1</a>, variante de leitura atribuída a Erasmo. Ver <span class=\"greek\">Ἔφεσος</span>. A fonte não lhe atribui outra ocorrência no corpus estudado.</p></section></article>\n<article id=\"entry-ephesios-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἐφέσιος, ία, ιον</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦Ephésios⟧</span><span class=\"separator\">·</span><span>adjetivo e gentílico</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">Ἐφέσιος</span>, <span class=\"greek\">ία</span>, <span class=\"greek\">ιον</span>. <strong>Efésio; proveniente de Éfeso</strong>. <span class=\"greek\">οἱ</span> <span class=\"greek\">Ἐ</span>., «os efésios» (frequente em inscrições; Fílon, Leg. ad Gai. 315; Josefo, Ant. 14, 224; Taciano 33, 2; Atenágoras 31, 1), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.27\" target=\"_blank\" rel=\"noopener noreferrer\">At 18:27</a>, códice D; 19:28, 34; 20:4, códice D; 21:29; subscrição de Ef; IEph 8:1; 11:2; IMg 15; ITr 13:1; IRo 10:1; IPhld 11:2; ISm 12:1.</p><p class=\"entry-text\"><span class=\"greek\">ἄνδρες</span> <span class=\"greek\">Ἐ</span>., «homens efésios» (como Aquiles Tácio 7, 9, 2), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.35\" target=\"_blank\" rel=\"noopener noreferrer\">At 19:35</a>a; AcPl Ha 1, 24. <span class=\"greek\">ἡ</span> <span class=\"greek\">Ἐφεσίων</span> <span class=\"greek\">πόλις</span>, «a cidade dos efésios» (cf. <span class=\"greek\">ἡ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">Ἱεροσολυμιτῶν</span> <span class=\"greek\">π</span>., «a cidade dos habitantes de Jerusalém», Josefo, Ant. 5, 82; 10, 109 e outros), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.35\" target=\"_blank\" rel=\"noopener noreferrer\">At 19:35</a>b. <span class=\"greek\">ἡ</span> <span class=\"greek\">Ἐφεσίων</span> <span class=\"greek\">ἐκκλησία</span>, «a igreja dos efésios», subscrição de 2Tm (para bibliografia sobre a carta aos efésios, ver S. Hanson, <em>The Unity of the Church in the NT</em> [1946], 173–90). Ver o verbete seguinte.</p></section></article>\n<article id=\"entry-ephesos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἔφεσος, ου, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦Éphesos⟧</span><span class=\"separator\">·</span><span>substantivo feminino; nome geográfico</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">Ἔφεσος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ἡ</span>. <strong>Éfeso</strong>, porto marítimo da Ásia Menor na planície do rio Caístro. Ver o verbete precedente. Heródoto e posteriores; frequentemente em inscrições; Josefo, SibOr; Atenágoras 17, 3. Cidade célebre por seu templo de Ártemis (ver <span class=\"greek\">Ἄρτεμις</span>). A congregação cristã em Éfeso foi fundada por Paulo ou aumentou muito graças ao seu ministério (G. Duncan, <em>St. Paul's Ephesian Ministry</em>, 1929).</p><p class=\"entry-text\"><a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.19\" target=\"_blank\" rel=\"noopener noreferrer\">At 18:19</a>, 21, 24, 27 (códice D); 19:1, 17, 26; 20:16s. (sobre a ambientação efésia do discurso paulino em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.17\" target=\"_blank\" rel=\"noopener noreferrer\">At 20:17</a>–38, D. Watson, em <em>Persuasive Artistry</em>, Festschrift G. A. Kennedy [1991], 185–86, nota 3); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.32\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 15:32</a>; 16:8; subscrição, variante; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 1:1</a> (a expressão referente a Éfeso falta em P46, Sinaítico e B; Márcion traz «aos laodicenses» em seu lugar; ver Harnack, SBBerlAk [1910], 696ss.; J. Schmid, <em>D. Eph des Ap. Pls</em>, 1928; Goodspeed, <em>Problems</em>, 171–73); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 1:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">2Tm 1:18</a>; 4:12; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 1:11</a> (a ordem Éfeso, Esmirna, Pérgamo, Sardes também ocorre em inscrição oficial de Mileto [56–50 a.C.]: T. Wiegand, <em>Milet</em>, caderno 2 [prefeitura], p. 101s.); 2:1.</p><p class=\"entry-text\"><strong>Bibliografia:</strong> O. Benndorf, <em>Z. Ortskunde u. Stadtgesch. von Eph.</em> (1905); L. Bürchner, «Ephesos», Pauly-W. V (1905), 2773–822; Österreichisches Archäologisches Institut, <em>Forschungen in Ephesos</em> I e seguintes (desde 1906), relatórios preliminares em <em>Jahreshefte</em> (desde 1922); J. Keil, <em>Ephesos</em>, 2.ª ed. (1930); W. Ramsay, <em>The Church in the Roman Empire before a.d. 170</em> (1912), 135–39; J. Bakhuizen van den Brink, <em>De oudchristelijke monumenten van Ephesus</em> (1923); V. Schultze, <em>Altchr. Städte u. Landsch.</em> II/2 (1926), 86–120; Deissmann, <em>D. Ausgrabungen in Eph.</em> (1926), ThBl 6 (1927), 17–19; «The Excavations in Ephesus», <em>Biblical Review</em> 15 (1930), 332–46; R. Tonneau, «E. au temps de S. Paul», RB 38 (1929), 5–34, 321–63; P. Antoine, <em>Dictionnaire de la Bible</em>, suplemento II (1934), 1076–1104; F. Rienecker, <em>Der Eph.</em> [com suplemento ilustrado] (1934); BA 8 (1945), 61–80; F. Miltner, <em>E., Stadt d. Artemis u. d. Joh.</em> (1954); H. Koester, <em>Ephesos, Metropolis of Asia</em> (1966); S. Friesen, Bar 19 (1993), 24–37. Ver <span class=\"greek\">Δημήτριος</span> ②. OEANE II 252–55; <em>Die Inschriften von Ephesos</em>, oito volumes (1979–84); G. Horsley, NovT 34 (1992), 105–68.</p></section></article>\n"};
